    return r.stdout.decode() if r.returncode==0 else None
def head_before_block(t):
    out=[]
    for line in t.split("\n"):
        if line.strip()==BLOCK: return "\n".join(out).rstrip()
        out.append(line)
    return None
repos=[p.name.replace("-lcv577","") for p in (WS/".worktrees").glob("*-lcv577")]
